mapper.select:
SELECT notification_id, member_id, type, title, content, link_url, is_read, created_at
FROM notification
WHERE member_id = #{memberId}
ORDER BY created_at DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.update:
UPDATE notification
SET is_read = true
WHERE notification_id = #{notificationId} AND member_id = #{memberId}
